from fractions import Fraction


def evaluate(expression):
    if not isinstance(expression, str):
        raise ValueError("Expression must be a string")

    pos = 0
    n = len(expression)

    def skip_whitespace():
        nonlocal pos
        while pos < n and expression[pos] in ' \t\n\r\f\v':
            pos += 1

    def parse_expr():
        nonlocal pos
        result = parse_term()
        skip_whitespace()
        while pos < n and expression[pos] in ('+', '-'):
            op = expression[pos]
            pos += 1
            right = parse_term()
            result = result + right if op == '+' else result - right
            skip_whitespace()
        return result

    def parse_term():
        nonlocal pos
        result = parse_factor()
        skip_whitespace()
        while pos < n and expression[pos] in ('*', '/'):
            op = expression[pos]
            pos += 1
            right = parse_factor()
            if op == '*':
                result = result * right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                result = result / right
            skip_whitespace()
        return result

    def parse_factor():
        nonlocal pos
        skip_whitespace()
        sign = 1
        while pos < n and expression[pos] in ('+', '-'):
            if expression[pos] == '-':
                sign = -sign
            pos += 1
            skip_whitespace()
        return sign * parse_primary()

    def parse_primary():
        nonlocal pos
        skip_whitespace()
        if pos >= n:
            raise ValueError("Missing operand")
        ch = expression[pos]
        if ch == '(':
            pos += 1
            result = parse_expr()
            skip_whitespace()
            if pos >= n or expression[pos] != ')':
                raise ValueError("Unmatched parenthesis")
            pos += 1
            return result
        if ch.isdigit():
            start = pos
            while pos < n and expression[pos].isdigit():
                pos += 1
            return Fraction(int(expression[start:pos]))
        raise ValueError(f"Unexpected character: {ch!r}")

    skip_whitespace()
    if pos >= n:
        raise ValueError("Empty expression")
    result = parse_expr()
    skip_whitespace()
    if pos < n:
        raise ValueError(f"Unexpected character: {expression[pos]!r}")
    return result
