def strongly_connected_components(graph):
    if not graph:
        return []

    # Collect all nodes: keys plus any neighbor-only nodes
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    # Build deduplicated adjacency (ignores duplicate edges)
    adj = {node: set() for node in all_nodes}
    for node, neighbors in graph.items():
        for n in neighbors:
            adj[node].add(n)

    # Tarjan's algorithm (iterative-friendly recursive form), O(V+E)
    index_counter = [0]
    index = {}
    lowlink = {}
    on_stack = set()
    stack = []
    sccs = []

    def strongconnect(v):
        index[v] = index_counter[0]
        lowlink[v] = index_counter[0]
        index_counter[0] += 1
        stack.append(v)
        on_stack.add(v)

        for w in adj[v]:
            if w not in index:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif w in on_stack:
                lowlink[v] = min(lowlink[v], index[w])

        if lowlink[v] == index[v]:
            component = []
            while True:
                w = stack.pop()
                on_stack.discard(w)
                component.append(w)
                if w == v:
                    break
            sccs.append(component)

    for v in all_nodes:
        if v not in index:
            strongconnect(v)

    # Sort each component, then sort the outer list lexicographically
    return sorted(sorted(comp) for comp in sccs)
